import sys

data = sys.stdin.read().split()
s = data[0]
n = len(s)
d = [[0] * n for _ in range(n)]
for i in range(n - 1, -1, -1):
    d[i][i] = 1
    for j in range(i + 1, n):
        if s[i] == s[j]:
            d[i][j] = d[i + 1][j - 1] + 2
        else:
            d[i][j] = max(d[i + 1][j], d[i][j - 1])
print(d[0][n - 1])

